macro_rules! is_dangling_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function is_dangling in module {}", module_path!());
    };
}

mkfn!{
    is_dangling_introspect!();
    pub (crate) fn is_dangling < T : ? Sized > (ptr : * const T) -> bool { (ptr . cast :: < () > ()) . addr () == usize :: MAX }
}
